begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select plan(29);

select throws_ok($$insert into schools(name, timezone) values (' ', 'Asia/Yerevan')$$, '23514', null, 'blank school name rejected');
select throws_ok($$insert into schools(name, timezone) values ('X', 'Mars/Olympus')$$, '23514', null, 'invalid timezone rejected');
select throws_ok($$insert into subjects(school_id,name,color) values ('aaaaaaaa-0000-0000-0000-000000000001','Ֆիզիկա','blue')$$, '23514', null, 'invalid color rejected');
select throws_ok($$insert into classes(school_id,name) values ('aaaaaaaa-0000-0000-0000-000000000001',' 5ա ')$$, '23505', null, 'trimmed case-insensitive Armenian class duplicate rejected');
select lives_ok($$insert into classes(id,school_id,name,public_id) values ('bbbbbbbb-1000-0000-0000-000000000099','bbbbbbbb-0000-0000-0000-000000000001','5Բ','bbbbbbbb-1100-0000-0000-000000000099')$$, 'same class name allowed in another school');
select throws_ok($$insert into subjects(school_id,name,color) values ('aaaaaaaa-0000-0000-0000-000000000001',' մաթեմատիկա ','#FFFFFF')$$, '23505', null, 'trimmed case-insensitive Armenian subject duplicate rejected');
select lives_ok($$insert into teachers(id,school_id,name) values ('aaaaaaaa-4000-0000-0000-000000000099','aaaaaaaa-0000-0000-0000-000000000001','Անի Սարգսյան')$$, 'duplicate teacher names allowed');
select throws_ok($$insert into lessons(school_id,class_id,weekday,time_slot_id,subject_id) values ('aaaaaaaa-0000-0000-0000-000000000001','aaaaaaaa-1000-0000-0000-000000000001',7,'aaaaaaaa-2000-0000-0000-000000000002','aaaaaaaa-3000-0000-0000-000000000001')$$, '23514', null, 'weekday outside 1..6 rejected');
select throws_ok($$insert into time_slots(school_id,start_time,end_time) values ('aaaaaaaa-0000-0000-0000-000000000001','15:00','14:00')$$, '23514', null, 'reversed time rejected');
select throws_ok($$insert into time_slots(school_id,start_time,end_time) values ('aaaaaaaa-0000-0000-0000-000000000001','15:00:01','16:00')$$, '23514', null, 'second precision rejected');
select throws_ok($$insert into time_slots(school_id,start_time,end_time) values ('aaaaaaaa-0000-0000-0000-000000000001','09:30','10:00')$$, '23P01', null, 'partial slot overlap rejected');
select throws_ok($$insert into time_slots(school_id,start_time,end_time) values ('aaaaaaaa-0000-0000-0000-000000000001','09:10','09:20')$$, '23P01', null, 'nested slot overlap rejected');
select throws_ok($$insert into time_slots(school_id,start_time,end_time) values ('aaaaaaaa-0000-0000-0000-000000000001','09:00','09:45')$$, '23P01', null, 'same slot interval rejected');
select lives_ok($$insert into time_slots(id,school_id,start_time,end_time) values ('aaaaaaaa-2000-0000-0000-000000000099','aaaaaaaa-0000-0000-0000-000000000001','09:45','10:00')$$, 'adjacent slot allowed');
select lives_ok($$insert into time_slots(id,school_id,start_time,end_time) values ('bbbbbbbb-2000-0000-0000-000000000099','bbbbbbbb-0000-0000-0000-000000000001','10:00','10:45')$$, 'same interval allowed in another school');
select throws_ok($$insert into lessons(school_id,class_id,weekday,time_slot_id,subject_id) values ('aaaaaaaa-0000-0000-0000-000000000001','aaaaaaaa-1000-0000-0000-000000000001',1,'aaaaaaaa-2000-0000-0000-000000000001','aaaaaaaa-3000-0000-0000-000000000001')$$, '23505', null, 'second lesson in same cell rejected');
select throws_ok($$insert into lessons(school_id,class_id,weekday,time_slot_id,subject_id,teacher_id) values ('aaaaaaaa-0000-0000-0000-000000000001','aaaaaaaa-1000-0000-0000-000000000002',1,'aaaaaaaa-2000-0000-0000-000000000001','aaaaaaaa-3000-0000-0000-000000000001','aaaaaaaa-4000-0000-0000-000000000001')$$, '23505', null, 'teacher conflict across classes rejected');
select lives_ok($$insert into lessons(id,school_id,class_id,weekday,time_slot_id,subject_id,teacher_id) values ('aaaaaaaa-5000-0000-0000-000000000099','aaaaaaaa-0000-0000-0000-000000000001','aaaaaaaa-1000-0000-0000-000000000002',2,'aaaaaaaa-2000-0000-0000-000000000001','aaaaaaaa-3000-0000-0000-000000000001',null)$$, 'null teacher is not occupancy constrained');
select lives_ok($$insert into lessons(id,school_id,class_id,weekday,time_slot_id,subject_id,teacher_id) values ('aaaaaaaa-5000-0000-0000-000000000098','aaaaaaaa-0000-0000-0000-000000000001','aaaaaaaa-1000-0000-0000-000000000002',2,'aaaaaaaa-2000-0000-0000-000000000002','aaaaaaaa-3000-0000-0000-000000000001',null)$$, 'another null teacher lesson is allowed');
select throws_ok($$insert into lessons(school_id,class_id,weekday,time_slot_id,subject_id) values ('aaaaaaaa-0000-0000-0000-000000000001','bbbbbbbb-1000-0000-0000-000000000001',3,'aaaaaaaa-2000-0000-0000-000000000001','aaaaaaaa-3000-0000-0000-000000000001')$$, '23503', null, 'cross-school class rejected by FK');
select throws_ok($$insert into lessons(school_id,class_id,weekday,time_slot_id,subject_id) values ('aaaaaaaa-0000-0000-0000-000000000001','aaaaaaaa-1000-0000-0000-000000000002',3,'bbbbbbbb-2000-0000-0000-000000000001','aaaaaaaa-3000-0000-0000-000000000001')$$, '23503', null, 'cross-school slot rejected by FK');
select throws_ok($$insert into lessons(school_id,class_id,weekday,time_slot_id,subject_id) values ('aaaaaaaa-0000-0000-0000-000000000001','aaaaaaaa-1000-0000-0000-000000000002',3,'aaaaaaaa-2000-0000-0000-000000000001','bbbbbbbb-3000-0000-0000-000000000001')$$, '23503', null, 'cross-school subject rejected by FK');
select throws_ok($$insert into lessons(school_id,class_id,weekday,time_slot_id,subject_id,teacher_id) values ('aaaaaaaa-0000-0000-0000-000000000001','aaaaaaaa-1000-0000-0000-000000000002',3,'aaaaaaaa-2000-0000-0000-000000000001','aaaaaaaa-3000-0000-0000-000000000001','bbbbbbbb-4000-0000-0000-000000000001')$$, '23503', null, 'cross-school teacher rejected by FK');
select throws_ok($$delete from subjects where id='aaaaaaaa-3000-0000-0000-000000000001'$$, '23503', null, 'used subject hard delete restricted');
select lives_ok($$update subjects set active=false where id='aaaaaaaa-3000-0000-0000-000000000001'$$, 'used subject can be archived');
select lives_ok($$update lessons set comment='փոփոխված' where id='aaaaaaaa-5000-0000-0000-000000000001'$$, 'comment edit keeps unchanged inactive link');
select throws_ok($$insert into lessons(school_id,class_id,weekday,time_slot_id,subject_id) values ('aaaaaaaa-0000-0000-0000-000000000001','aaaaaaaa-1000-0000-0000-000000000002',4,'aaaaaaaa-2000-0000-0000-000000000001','aaaaaaaa-3000-0000-0000-000000000001')$$, '23514', null, 'new lesson cannot use inactive subject');
select lives_ok($$insert into schedule_publications(id,school_id,class_id,revision,format_version,payload) values ('aaaaaaaa-6000-0000-0000-000000000001','aaaaaaaa-0000-0000-0000-000000000001','aaaaaaaa-1000-0000-0000-000000000001',1,1,'{}')$$, 'valid publication allowed by constraints');
select throws_ok($$insert into schedule_publications(school_id,class_id,revision,format_version,payload) values ('bbbbbbbb-0000-0000-0000-000000000001','aaaaaaaa-1000-0000-0000-000000000001',2,1,'{}')$$, '23503', null, 'publication cross-school class rejected');

select * from finish();
rollback;
